#!/usr/bin/env python3
"""Regenerate .github/prompts/README.md, an index of prompt files grouped by status.

Usage: python3 .github/skills/prompt-workflow/scripts/build_index.py [--check] [--root <dir>]

Args:
  --check         Don't write; exit 1 if a status is missing/invalid or a README.md is stale
  --root <dir>    Repo to index (default: the repo this script lives in)
  -h, --help      Show this help

Steps:   find every .github/prompts/ dir under root (skipping vendored/hidden dirs),
         read each *.md file's front-matter status, title and unanswered clarifications,
         write (or compare) README.md per dir
Inputs:  <dir>/.github/prompts/*.md and <dir>/**/.github/prompts/*.md
Outputs: README.md in each prompts dir (not with --check)

Examples:
  python3 .github/skills/prompt-workflow/scripts/build_index.py
  python3 .github/skills/prompt-workflow/scripts/build_index.py --check
"""

from __future__ import annotations

import argparse
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import quote

# Group order in the index; also the set of valid statuses.
GROUPS = [
    ("in-progress", "In progress"),
    ("open", "Open"),
    ("parked", "Parked"),
    ("reference", "Reference"),
    ("done", "Done"),
]
VALID = {status for status, _ in GROUPS}
NO_STATUS = "No status"
SKIP_DIRS = {"node_modules", "venv", "__pycache__", "dist", "build", "site-packages"}
HEADER = (
    "<!-- Generated by .github/skills/prompt-workflow/scripts/build_index.py."
    " Do not edit by hand. -->\n"
)
DATE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})(?:_(\d{2})(\d{2}))?")
FENCE_RE = re.compile(r"^\s*(`{3,}|~{3,})")


@dataclass
class PromptFile:
    path: Path
    status: str | None
    title: str
    open_clarifications: int

    @property
    def date(self) -> str:
        m = DATE_RE.match(self.path.name)
        if not m:
            return ""
        return f"{m[1]} {m[2]}:{m[3]}" if m[2] else m[1]


def _unfenced(lines):
    """Yield the lines that are outside fenced code blocks."""
    fence = None
    for line in lines:
        m = FENCE_RE.match(line)
        if fence is None:
            if m:
                fence = m[1]
                continue
            yield line
        elif m and m[1][0] == fence[0] and len(m[1]) >= len(fence) and not line.strip()[len(m[1]):]:
            fence = None


def _readable_name(path: Path) -> str:
    """Fallback title: file name without date prefix or .prompt suffix, separators as spaces."""
    stem = path.stem.removesuffix(".prompt")
    stem = DATE_RE.sub("", stem).lstrip("_- ")
    return re.sub(r"[-_]+", " ", stem).strip() or path.stem


def parse(path: Path) -> PromptFile:
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    status = None
    body = lines
    if lines and lines[0].strip() == "---":
        for i, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                body = lines[i + 1 :]
                break
            key, sep, value = line.partition(":")
            if sep and key.strip() == "status":
                status = value.split("#", 1)[0].strip().strip("\"'") or None

    title = _readable_name(path)
    open_clarifications = 0
    in_clarifications = False
    found_title = False
    for line in _unfenced(body):
        if not found_title and line.startswith("# "):
            title = line[2:].strip()
            found_title = True
        if line.startswith("## "):
            in_clarifications = line[3:].strip().lower().startswith("clarifications")
        elif in_clarifications and line.strip() == ">":
            open_clarifications += 1
    return PromptFile(path, status, title, open_clarifications)


def find_prompt_dirs(root: Path) -> list[Path]:
    found = []
    for dirpath, dirnames, _ in os.walk(root):
        dirnames[:] = [
            d for d in dirnames if d not in SKIP_DIRS and (not d.startswith(".") or d == ".github")
        ]
        current = Path(dirpath)
        if current.name == ".github":
            dirnames[:] = [d for d in dirnames if d == "prompts"]
        elif current.name == "prompts" and current.parent.name == ".github":
            found.append(current)
            dirnames[:] = []
    return sorted(found, key=lambda p: str(p))


def prompt_files(prompts_dir: Path) -> list[PromptFile]:
    return [
        parse(p)
        for p in sorted(prompts_dir.glob("*.md"))
        if p.is_file() and p.name != "README.md"
    ]


def render(files: list[PromptFile]) -> str:
    out = [HEADER, "# Prompt files\n"]
    if not files:
        out.append("\n_No prompt files yet._\n")
        return "".join(out)
    groups = [(label, [f for f in files if f.status == status]) for status, label in GROUPS]
    groups.append((NO_STATUS, [f for f in files if f.status not in VALID]))
    for label, members in groups:
        if not members:
            continue
        members.sort(key=lambda f: (f.date, f.path.name), reverse=True)
        out.append(f"\n## {label} ({len(members)})\n\n")
        out.append("| Date | Prompt | Open clarifications |\n| --- | --- | --- |\n")
        for f in members:
            title = f.title.replace("|", "\\|")
            count = str(f.open_clarifications) if f.open_clarifications else ""
            out.append(f"| {f.date} | [{title}]({quote(f.path.name)}) | {count} |\n")
    return "".join(out)


def _status_problems(files: list[PromptFile]) -> list[str]:
    return [
        f"{f.path}: missing status" if f.status is None else f"{f.path}: invalid status '{f.status}'"
        for f in files
        if f.status not in VALID
    ]


def build(root: Path) -> list[str]:
    """Write README.md in every prompts dir. Returns status warnings."""
    warnings = []
    for prompts_dir in find_prompt_dirs(root):
        files = prompt_files(prompts_dir)
        (prompts_dir / "README.md").write_text(render(files), encoding="utf-8")
        warnings += _status_problems(files)
    return warnings


def check(root: Path) -> list[str]:
    """Return every problem found; an empty list means all good."""
    problems = []
    for prompts_dir in find_prompt_dirs(root):
        files = prompt_files(prompts_dir)
        problems += _status_problems(files)
        readme = prompts_dir / "README.md"
        if not readme.is_file():
            problems.append(f"{readme}: missing")
        elif readme.read_text(encoding="utf-8") != render(files):
            problems.append(f"{readme}: out of date (run build_index.py)")
    return problems


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[4])
    parser.add_argument("-h", "--help", action="store_true")
    args, unknown = parser.parse_known_args(argv)
    if args.help:
        print(__doc__.strip())
        return 0
    if unknown:
        print(f"error: unknown argument '{unknown[0]}' (run with --help for usage)", file=sys.stderr)
        return 1
    root = args.root.resolve()
    if args.check:
        problems = check(root)
        for p in problems:
            print(p)
        return 1 if problems else 0
    for w in build(root):
        print(f"warning: {w}", file=sys.stderr)
    for d in find_prompt_dirs(root):
        print(f"wrote {d / 'README.md'}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
